"""Generated by solo-to-scale; edit `templates/tools/claim.py` in the plugin, then run upgrade.

Claim a story-group issue before starting work, so two sessions never work on the same thing.

  python tools/claim.py <issue>             # claim through `gh api`: label `claimed`, assign yourself
  python tools/claim.py <issue> --dry-run   # show what would happen; change nothing
  python tools/claim.py <issue> --from-json issue.json --dry-run   # offline (tests, no gh)

Refuses an issue already labelled `claimed`, and takes the same atomic lock as `tickets.py claim` (a
`refs/claims/<issue>` ref), so two sessions racing for one issue can't both win. Prints the goal chain to start the session with and
records it in .claude/state/claimed.json, which the session-start hook shows.
"""
from __future__ import annotations

import argparse
import json
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import tickets  # noqa: E402


def gh(*args: str, payload: dict | None = None) -> dict:
    cmd = ["gh", "api", *args]
    if payload is not None:
        cmd += ["--input", "-"]
    out = subprocess.run(cmd, input=json.dumps(payload) if payload is not None else None,
                         capture_output=True, text=True, check=True)
    return json.loads(out.stdout or "{}")


def section(body: str, heading: str) -> list[str]:
    lines, inside = [], False
    for line in (body or "").splitlines():
        if line.startswith("## "):
            if inside:
                break
            inside = line[3:].strip().lower().startswith(heading.lower())
            continue
        if inside and line.strip():
            lines.append(line.strip().lstrip("-* ").strip())
    return lines


def owner_role(body: str) -> str | None:
    for line in section(body, "Owner"):
        for part in line.replace("`", "").split():
            if part.startswith("role:"):
                return part
    return None


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Claim a story-group issue")
    ap.add_argument("issue", type=int)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--from-json", type=Path, help="read the issue from a file instead of gh")
    ap.add_argument("--root", type=Path, default=s.ROOT)
    args = ap.parse_args(argv)
    repo = s.project(args.root).get("repo", "")
    issue = json.loads(args.from_json.read_text(encoding="utf-8")) if args.from_json else gh(f"repos/{repo}/issues/{args.issue}")
    labels = [lb["name"] if isinstance(lb, dict) else lb for lb in issue.get("labels", [])]
    if "claimed" in labels:
        print(f"refused: #{args.issue} is already claimed; pick another issue or ask the founder")
        return 1
    chain = section(issue.get("body", ""), "Goal chain")
    role = owner_role(issue.get("body", ""))
    add = ["claimed"] + ([role] if role and role not in labels else [])
    print(f"Claim #{args.issue}: {issue.get('title', '')}")
    print(f"  labels to add: {', '.join(add)}; assign: you")
    if args.dry_run:
        print("  dry run: nothing changed")
    else:
        holder = tickets.Hub(repo).lock(args.issue, role or "a-session")
        if holder is not None:
            print(f"refused: #{args.issue} was just claimed by {holder}; pick another issue or ask the founder")
            return 1
        gh(f"repos/{repo}/issues/{args.issue}/labels", "-X", "POST", payload={"labels": add})
        me = gh("user").get("login")
        if me:
            gh(f"repos/{repo}/issues/{args.issue}/assignees", "-X", "POST", payload={"assignees": [me]})
        state = args.root / ".claude" / "state"
        state.mkdir(parents=True, exist_ok=True)
        (state / "claimed.json").write_text(json.dumps(
            {"issue": args.issue, "title": issue.get("title", ""), "goal_chain": chain}), encoding="utf-8")
    print("Goal chain:")
    for line in chain or ["(none in the issue: add it from the story-group template)"]:
        print(f"  {line}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
